changeSet.sql:
INSERT INTO permissions (name, description) VALUES ('plugin_locker24_health_access', 'Access to the fleet health dashboard and alerts');
INSERT INTO userRolePermissions (roleId, permissionId)
    SELECT id, currval('permissions_id_seq')
    FROM userroles;

CREATE TABLE locker24_health_settings (
    customer_id INT PRIMARY KEY REFERENCES customers (id) ON DELETE CASCADE,
    webhook_url VARCHAR(1024),
    time_zone VARCHAR(64) NOT NULL DEFAULT 'Europe/Sarajevo'
);
